solutionReferences.cpp:
#include <iostream>

int main() {
    int nota = 85;
    if (nota >= 90) {
        std::cout << "Excelente (A)" << std::endl;
    } else if (nota >= 80) {
        std::cout << "Muy Bien (B)" << std::endl;
    } else if (nota >= 70) {
        std::cout << "Bien (C)" << std::endl;
    } else {
        std::cout << "Necesitas mejorar (D)" << std::endl;
    }
    return 0;
}
